  Project copyWith({
    int? id,
    String? name,
    String? address,
    double? latitude,
    double? longitude,
    int? createdAt,
    int? updatedAt,
    Value<int?> activeModuleTypeId = const Value.absent(),
    Value<int?> activeInverterId = const Value.absent(),
    double? tAmbientMinC,
    double? tAmbientMaxC,
    int? gridPhases,
