    bza: bza ?? this.bza,
    wbLeitungM: wbLeitungM ?? this.wbLeitungM,
    batKwh: batKwh ?? this.batKwh,
    batUnits: batUnits ?? this.batUnits,
    batDcA: batDcA ?? this.batDcA,
    batAcKw: batAcKw ?? this.batAcKw,
    batAussen: batAussen ?? this.batAussen,
