  final int? mppIndex;

  /// DC cable cross-section in mm² (VDE 0100-443). Null = not specified.
  final double? dcCableMm2;

  /// Installed DC fuse rating in A. Null = not specified.
  final double? fuseA;
  const ModuleString({
    required this.id,
    required this.projectId,
